      },
      {
        area: 'addon alignment',
        level: 'flexible',
        note: 'InputGroupAddon align is inline-start (leading) or inline-end (trailing)',
      },
      {
        area: 'addon content',
        level: 'flexible',
        note: 'prefix/suffix and addon children accept arbitrary ReactNode',
